sql.where:
deleted = 0

    AND order_id = #{orderId}


    AND receivable_status = #{receivableStatus}


    AND owner_id = #{ownerId}


    AND due_date >= #{dueDateFrom}


    AND due_date <= #{dueDateTo}


    AND receivable_status != 'PAID'
    AND due_date IS NOT NULL
    AND due_date < CURDATE()
